class Template:
    """One representative WTP->AC control message (full wire)."""

    def __init__(self, name, mtype, seq, hex, resp_hex=None):
        self.name = name
        self.mtype = mtype
        self.seq = seq
        self.hex = hex
        self.resp_hex = resp_hex

    @property
    def wire(self):
        return bytes.fromhex(self.hex)

    @property
    def resp_wire(self):
        return bytes.fromhex(self.resp_hex) if self.resp_hex else None


